pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface BossBaby {
    function owner() external view returns (address);
    function enableTrading() external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function swapTokensAtAmount() external view returns (uint256);
    function tradingEnabled() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xD8dBE5AC60cD1c0b40C9182cB3eB2392d3df371F;
    address attacker = address(this);
    BossBaby bossBaby;

    // ─── Setup ───────────────────────────────────────
    function setUp() public {
        bossBaby = BossBaby(TARGET);
        vm.label(TARGET, "BossBaby Token");
        vm.label(address(this), "Attacker");

        // Inject tokens for testing (decimals = 9)
        deal(TARGET, address(this), 1000000 * 1e9);
    }

    // ─── Exploit ─────────────────────────────────────
    function testExploit() public {

        // Step 1: Read private liquidity fee storage slots
        // Based on state variable order: liquidityFeeonBuy at slot 15, liquidityFeeonSell at slot 16
        uint256 liquidityFeeBuy = uint256(vm.load(TARGET, bytes32(uint256(15))));
        uint256 liquidityFeeSell = uint256(vm.load(TARGET, bytes32(uint256(16))));
        uint256 totalLiquidityFee = liquidityFeeBuy + liquidityFeeSell;

        // Oracle verification: liquidity fees must equal 0
        assertEq(totalLiquidityFee, 0, "Liquidity fees should be hardcoded to 0");

        // Step 2: Get swap threshold and transfer tokens to contract
        uint256 swapThreshold = bossBaby.swapTokensAtAmount();
        bossBaby.transfer(TARGET, swapThreshold * 2);

        // Step 3: Verify contract accumulated tokens (proving transfer worked)
        uint256 contractBalance = bossBaby.balanceOf(TARGET);
        assertGt(contractBalance, 0, "Contract should hold tokens after transfer");

        // Step 4: Re-verify liquidity fees still equal 0 (cannot be modified by anyone)
        liquidityFeeBuy = uint256(vm.load(TARGET, bytes32(uint256(15))));
        liquidityFeeSell = uint256(vm.load(TARGET, bytes32(uint256(16))));
        assertEq(liquidityFeeBuy + liquidityFeeSell, 0, "VULNERABILITY CONFIRMED: Liquidity fees permanently 0, no liquidity will ever be added");
        assertEq(liquidityFeeBuy + liquidityFeeSell, 0, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

